    mv a1, s2
    lw t1, 4(sp)
    mv a2, t1
    jal ra, ga_rd_bulk
    lw t1, 4(sp)
    add t1, t1, 4
    add s5, s5, t1
    slli s5, s5, 20
    srli s5, s5, 20
    mv a1, s5
    li a0, 0x200C
    jal ra, ga_wr32
    lw ra, 12(sp)
    addi sp, sp, 16
    jalr zero, 0(ra)
    ga_wait_cc:
    addi sp, sp, -16
    sw ra, 12(sp)
    sw s8, 8(sp)
    lui s8, 0x31
    addi s8, s8, -704
    ga_wcc_poll:
    jal ra, ga_poll_b2h
    bnez a0, ga_wcc_got
    addi s8, s8, -1
    bnez s8, ga_wcc_poll
    addi a0, zero, 1
    lw s8, 8(sp)
    lw ra, 12(sp)
    addi sp, sp, 16
    jalr zero, 0(ra)
    ga_wcc_got:
    jal ra, ga_read_ev
    lbu t0, 0(s2)
    addi t1, zero, 14
    bne t0, t1, ga_wcc_bad
    lbu t0, 5(s2)
    bnez t0, ga_wcc_bad
    addi a0, zero, 0
    lw s8, 8(sp)
    lw ra, 12(sp)
    addi sp, sp, 16
    jalr zero, 0(ra)
    ga_wcc_bad:
    addi a0, zero, 1
    lw s8, 8(sp)
    lw ra, 12(sp)
    addi sp, sp, 16
    jalr zero, 0(ra)

halt:
    j halt


print_string:                # a0 = ptr
    addi sp, sp, -16
    sw ra, 12(sp)
    sw t0, 8(sp)
    sw t1, 4(sp)
ps_loop:
    lbu t1, 0(a0)
    beqz t1, ps_done
    lui t0, 0x40070
    sw t1, 0(t0)
    addi a0, a0, 1
    j ps_loop
ps_done:
    lw ra, 12(sp)
    lw t0, 8(sp)
    lw t1, 4(sp)
    addi sp, sp, 16
    ret

print_hex32:                 # a0 = word: 8 hex digits + newline
    addi sp, sp, -16
    sw ra, 12(sp)
    sw t1, 8(sp)
    sw t2, 4(sp)
    addi t2, zero, 8
    mv t1, a0
hex_digit:
    srli a0, t1, 28
    slli t1, t1, 4
    addi t0, zero, 10
    bgeu a0, t0, hex_alpha
    addi a0, a0, 0x30
    j hex_out
hex_alpha:
    addi a0, a0, 0x37
hex_out:
    lui t0, 0x40070
    sw a0, 0(t0)
    addi t2, t2, -1
    bnez t2, hex_digit
    addi a0, zero, 0x0A
    lui t0, 0x40070
    sw a0, 0(t0)
    lw ra, 12(sp)
    lw t1, 8(sp)
    lw t2, 4(sp)
    addi sp, sp, 16
    ret

uart_getc:                   # -> a0 = byte (blocks)
    lui t0, 0x40070
ug_wait:
    lw t1, 0x18(t0)
    andi t1, t1, 0x10
    bnez t1, ug_wait
    lw a0, 0(t0)
    andi a0, a0, 0xFF
    ret


